#include <vector>

class Solution {
public:
    bool canReachInEvenKnightMoves(std::vector<int>& startPos, std::vector<int>& endPos) {
        return (startPos[0] + startPos[1]) % 2 == (endPos[0] + endPos[1]) % 2;
    }
};

class Solution {
    public boolean canReachInEvenKnightMoves(int[] startPos, int[] endPos) {
        return (startPos[0] + startPos[1]) % 2 == (endPos[0] + endPos[1]) % 2;
    }
}

